<?php declare(strict_types=1);require dirname(__DIR__,2).'/includes/bootstrap.php';require_permission('wallet.reverse');if(!is_post()){http_response_code(405);header('Allow: POST');exit('Method not allowed');}verify_csrf();$id=filter_var(input('transaction_id'),FILTER_VALIDATE_INT);try{if(!$id)throw new InvalidArgumentException('Invalid transaction.');$result=wallet_reverse($id,trim((string)input('reason')),(int)admin()['id']);flash('success','Reversal completed: '.$result['transaction_id']);}catch(Throwable $e){flash('error',$e instanceof PDOException?'Could not complete reversal.':$e->getMessage());}redirect('/admin/wallets/index.php');
